// Writes src/data/exercise-video.ts: one require() per assets/exercises-video/<id>.mp4, so the app
// plays a looping clay video where one exists and falls back to the still images everywhere else.
// Run after adding videos: node scripts/gen-video-index.cjs
const fs = require('fs');
const path = require('path');
const dir = path.join(__dirname, '..', 'assets', 'exercises-video');
const ids = fs.existsSync(dir) ? fs.readdirSync(dir).filter((f) => f.endsWith('.mp4')).map((f) => f.slice(0, -4)).sort() : [];
const lines = [
  '// Generated by scripts/gen-video-index.cjs. Do not edit by hand.',
  '// Looping clay videos (start -> end -> start, 2.5 s, 1024 px). Exercises not listed use their stills.',
  'export const EXERCISE_VIDEO: Record<string, number> = {',
  ...ids.map((id) => `  ${/^[a-z_][a-z0-9_]*$/.test(id) ? id : JSON.stringify(id)}: require('../../assets/exercises-video/${id}.mp4'),`),
  '};',
  '',
];
fs.writeFileSync(path.join(__dirname, '..', 'src', 'data', 'exercise-video.ts'), lines.join('\n'));
console.log(ids.length, 'videos');
